files.callout.css:
html, body { margin: 0; background: transparent; }
body { font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
.callout {
  box-sizing: border-box;
  height: 100vh;
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 14px 16px;
  border-radius: 10px;
  border-left: 5px solid;
  overflow: auto;
}
.callout p { margin: 0; white-space: pre-wrap; }
.icon { font-size: 20px; line-height: 1.1; }
.tip { background: #e8f5e9; border-color: #43a047; color: #1b3d1f; }
.note { background: #e3f2fd; border-color: #1e88e5; color: #0d2a45; }
.warning { background: #fff8e1; border-color: #ffb300; color: #4a3500; }
@media (prefers-color-scheme: dark) {
  .tip { background: #1b2e1d; color: #c8e6c9; }
  .note { background: #132739; color: #bbdefb; }
  .warning { background: #33290c; color: #ffe082; }
}

files.callout.js:
// Draws one callout from its item data: {text, tone}.
const item = doctreeEmbed.json() || { text: doctreeEmbed.data, tone: 'tip' };
const icons = { tip: '💡', note: 'ℹ️', warning: '⚠️' };
const tone = icons[item.tone] ? item.tone : 'tip';
document.getElementById('box').classList.add(tone);
document.getElementById('icon').textContent = icons[tone];
document.getElementById('text').textContent = item.text || '';

files.main.js:
// Callouts: puts the selected text — or a line the user types — in a
// coloured box. The tone comes from its first word: "Warning…" is amber,
// "Note…" is blue, anything else is a green tip.
const toneOf = (text) => {
  const first = text.trim().split(/\s+/)[0].toLowerCase().replace(/[^a-z]/g, '');
  if (['warning', 'careful', 'caution', 'danger'].includes(first)) return 'warning';
  if (['note', 'info', 'fyi'].includes(first)) return 'note';
  return 'tip';
};

doctree.commands.register('insert', async () => {
  let text = (await doctree.document.getSelection()).trim();
  if (!text) {
    const last = await doctree.storage.get('last');
    text = ((await doctree.ui.prompt('Callout text', last || '')) || '').trim();
    if (!text) return;
    await doctree.storage.set('last', text);
  }
  await doctree.document.insertEmbed('box', { text, tone: toneOf(text) });
});
